ssh -v {{sshuser}}@{{host}} 2>&1 | grep -iE 'offering|authenticat|identity'
ssh-add -l                                      # keys currently loaded in the agent
ssh-copy-id -i ~/.ssh/id_ed25519.pub {{sshuser}}@{{host}}

Host {{host}}
  User {{sshuser}}
  IdentityFile ~/.ssh/id_ed25519
  IdentitiesOnly yes
